mapper.select:
SELECT COUNT(*)
FROM shopion.tOrdOrderProd OP
INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo
WHERE OP.OrderNo = #{orderNo} AND OP.OrderProdNo = #{orderProdNo}
AND OP.ShopCode = #{shopCode}
AND O.ChnlCode = #{chnlCode}

    AND EXISTS (SELECT 1 FROM shopwizard.tCmpChnl Ch WHERE Ch.ChnlCode = O.ChnlCode AND Ch.SvcCode = #{svcCode})

SELECT COUNT(*)
FROM shopion.tOrdOrder O
WHERE O.OrderNo = #{orderNo}
AND O.ChnlCode = #{chnlCode}

    AND EXISTS (SELECT 1 FROM shopion.tOrdOrderProd OP WHERE OP.OrderNo = O.OrderNo AND OP.ShopCode = #{shopCode})


    AND EXISTS (SELECT 1 FROM shopwizard.tCmpChnl Ch WHERE Ch.ChnlCode = O.ChnlCode AND Ch.SvcCode = #{svcCode})

SELECT COUNT(*) FROM shopwizard.tCatProd P WHERE P.ProdCode = #{prodCode}
AND P.ShopCode = #{shopCode}

    AND EXISTS (SELECT 1 FROM shopwizard.tCmpShop S WHERE S.ShopCode = P.ShopCode AND S.SvcCode = #{svcCode})

SELECT COUNT(*) FROM shopion.tPrdProd P WHERE P.ProdCode = #{prodCode}
AND P.ShopCode = #{shopCode}

    AND EXISTS (SELECT 1 FROM shopwizard.tCmpShop S WHERE S.ShopCode = P.ShopCode AND S.SvcCode = #{svcCode})

SELECT COUNT(*) FROM shopwizard.tAdjAdjust A WHERE A.AdjustNo = #{adjustNo}
AND A.ShopCode = #{shopCode}
AND A.ChnlCode = #{chnlCode}

    AND EXISTS (SELECT 1 FROM shopwizard.tCmpShop S WHERE S.ShopCode = A.ShopCode AND S.SvcCode = #{svcCode})
